solution.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();

        StringBuilder chiziq = new StringBuilder();
        for (int d = 1; d <= n; d++) {
            if (n % d == 0) {
                chiziq.append(" ").append(d);
            }
        }

        System.out.println(chiziq.toString().trim());
    }
}

solution.cpp:
#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    bool birinchi = true;
    for (int d = 1; d <= n; d++) {
        if (n % d == 0) {
            if (!birinchi) {
                cout << " ";
            }
            cout << d;
            birinchi = false;
        }
    }
    cout << endl;

    return 0;
}
